const fallback = {
 1:'Para resolver esta cuestión, comprueba el sentido de la oración completa y la función de cada palabra. Descarta opciones que cambien la idea, no concuerden o introduzcan una relación gramatical incorrecta.',
 2:'El conocimiento del entorno permite confirmar el destino y planificar una ruta razonable. Relaciona el dato con su zona o función y comprueba los accesos actuales antes de un servicio real.',
 3:'El criterio profesional es preservar seguridad, autonomía y trato respetuoso. La ayuda se adapta a la necesidad real del pasajero y no debe crear riesgos ni sustituir innecesariamente su decisión.',
 4:'Distingue el requisito de la actividad, el del vehículo y el del conductor. El cumplimiento debe mantenerse durante la prestación; un documento o condición no sustituye automáticamente a los demás.'
};
const explanations = {};
for (const q of bank) {
 const good = q.options.find(o=>o.id===q.correct).text;
 const combined = q.text+' '+good;
 let text = direct[q.id];
 if (!text) {
  const rule = rules[q.module].find(([rx])=>rx.test(combined));
  text = `La clave del documento selecciona «${good.replace(/[.]$/,'')}». ${rule?.[1] || fallback[q.module]}`;
 }
 const entry = {text};
 if(notes[q.id]) entry.note = notes[q.id];
 if(/101\/2016/.test(q.text)) entry.note ??= 'Esta pregunta conserva la referencia histórica del PDF al Decreto 101/2016. El Decreto 59/2026 actualiza los distintivos; la Comunidad de Madrid anuncia los nuevos desde el 3 de noviembre de 2026.';
 if(q.module===4 && /captar clientes.*grave|captación de clientes|captación.*infracción|clientes.*infracción/i.test(combined)) entry.note ??= 'Las muestras califican conductas próximas de captación de forma diferente. Se conserva esta clave; contrasta el supuesto exacto y la norma antes de generalizar la categoría sancionadora.';
 explanations[q.id] = entry;
}
